export const LAENDER_PRAEFIX_AKTIV = false;

/** Pfadschlüssel → interner Pfad (oder null bei unbekanntem Schlüssel). */
export function zielPfad(schluessel, land, { praefix = LAENDER_PRAEFIX_AKTIV } = {}) {
