export const sitemapUrls = (siteUrl) => SITEMAP_IDS.map((id) => `${siteUrl}/sitemap/${id}.xml`);

/**
 * Stammseiten der bisherigen Sitemap (ohne Länderpräfix). Entwurfsseiten filtert sitemap.js mit
