});
after(async () => browser?.close());

/** GET ohne Weiterleitung; bei Neustart/Kompilieren des Dev-Servers bis zu 3 Versuche. */
async function hole(pfad, headers = {}) {
  for (let v = 1; ; v++) {
    try {
      const r = await fetch(BASIS + pfad, { redirect: "manual", headers, signal: AbortSignal.timeout(180_000) });
      if (r.status >= 500 && v < 3) {
        await new Promise((ok) => setTimeout(ok, 4000));
        continue;
      }
      return r;
    } catch (e) {
      if (v >= 3) throw e;
      await new Promise((ok) => setTimeout(ok, 5000));
    }
  }
}

const praefix = (land) => land.toLowerCase();
const url = (k, land) => `/${praefix(land)}${k}`;

// Prüfmenge: in DE alle Seiten (vollständig); in AT/CH alle freigegebenen und je Gruppe Stichproben nicht freigegebener
function pruefmenge() {
  const regionen = ["/regionen/bayern", "/regionen/tirol", "/regionen/schweiz"];
  const statisch = Object.keys(SEITEN).filter((k) => !SEITEN[k].dynamisch);
  const faelle = [];
  for (const land of LAND_CODES) {
    for (const k of [...statisch, ...regionen]) {
      const st = stufe(k, land);
      if (land !== "DE" && !st && !["/rechner/pacht", "/agri-pv", "/kommunen", "/faq", "/marktdaten/fristen", "/regionen", "/energiegemeinschaften/rechner", ...regionen].includes(k)) continue;
      faelle.push({ land, k, erwartet: st ? 200 : 404, st });
    }
  }
  return faelle;
}

